  .page-width--product-main .product__info-container variant-selects .product-form__input:last-child {
    margin-bottom: 0 !important;
  }

  .page-width--product-main .product__info-container .product-form__input .form__label,
  .page-width--product-main .product__info-container .product-form__quantity .quantity__label {
    margin-bottom: 0.6rem !important;
    font-size: 1.05rem !important;
    letter-spacing: 0.08em !important;
  }

  .page-width--product-main .product__info-container variant-selects .product-form__input .select,
  .page-width--product-main .product__info-container variant-selects .product-form__input select {
    max-width: 100%;
  }

  .page-width--product-main .product__info-container variant-selects .product-form__input select {
    min-height: 4.4rem;
    border: 1px solid #d9d5d1 !important;
    border-radius: 10px !important;
    background: #ffffff !important;
    color: #1f1f1f !important;
    font-size: 1.6rem !important;
    line-height: 1.2;
    padding: 1.1rem 3.8rem 1.1rem 1.2rem !important;
