  }

  .page-width--product-main .product__info-container variant-selects .product-form__input select:focus {
    border-color: #1f1f1f !important;
    box-shadow: 0 0 0 0.2rem rgba(31, 31, 31, 0.09) !important;
  }

  .page-width--product-main .product__info-container .product-form__quantity {
    padding-bottom: 1rem;
  }

  .page-width--product-main .product__info-container .product-form__quantity .price-per-item__container {
    max-width: 100%;
    min-width: 0;
  }

  .page-width--product-main .product__info-container .product-form__quantity .quantity {
    min-height: 4.4rem;
